const assert=require("node:assert/strict");
const fs=require("node:fs");
const source=fs.readFileSync("src/app/page.tsx","utf8");
const start=source.indexOf('const marker = await cache.match(markerRequest);');
const end=source.indexOf('setLocationMessage("Valitse sijainti tai käytä omaa sijaintia.");',start);
const branch=source.slice(start,end);
assert.match(branch,/if \(!marker\)/,"missing boot marker enters fresh-store branch");
assert.match(branch,/localStorage\.removeItem\(STORE_SELECTION_STORAGE_KEY_V343\)/);
assert.match(branch,/localStorage\.removeItem\(STABLE_BOOT_SNAPSHOT_STORAGE_KEY_V505\)/);
assert.match(branch,/writeManualStoreOverridesV786\(\{\}\)/);
assert.match(branch,/setStoreModeChosenV299\(false\)/);
assert.match(branch,/setSelectedChains\(\{ s: false, k: false, lidl: false, tokmanni: false \}\)/);
assert.match(branch,/setFoundStores\(\[\]\)/);
assert.match(branch,/setActiveArea\(\{/);
assert.match(branch,/setGpsCoordsV320\(null\)/);
assert.match(branch,/setLocationInput\(""/);
assert.match(branch,/setUsingOwnLocation\(false\)/);
assert.match(branch,/writeManualStoreOverridesV786\(\{\}\)/);
const clearBranch=branch;
assert.equal(/if \(!marker\)/.test(clearBranch),true);
const reloadPath=source.slice(source.indexOf('if (marker) {',start),source.indexOf('if (marker) {',start)+1200);
assert.doesNotMatch(reloadPath,/removeItem\(STORE_SELECTION_STORAGE_KEY_V343\)/);
console.log("PASS real cache-clear marker branch resets store UI and selection state");
console.log("PASS ordinary reload marker path does not clear stored store selection");
